'use strict';
const START_KEY='antar-start-screen-v1',REVISIT_KEY='antar-revisit-v1';
let openingScreen='home',revisitState={enabled:false},revisitSession=null,revisitDismissed=false;
try{openingScreen=AntarLiving.start(localStorage.getItem(START_KEY));const saved=JSON.parse(localStorage.getItem(REVISIT_KEY)||'{}');revisitState={enabled:saved.enabled===true,lastShownAt:typeof saved.lastShownAt==='string'?saved.lastShownAt:''}}catch{}
let mapFocus='',mapTarget='',mapLabel='',experimentTitle='',experimentPlan='',experimentEditing='',experimentResult='',experimentOutcome='unsure',experimentState='done',experimentVersion='',experimentMeaning='',experimentEnergy='';
function decodeThoughtRoute(value){try{return decodeURIComponent(value)}catch{return ''}}
function spaceIcon(name){const paths={mind:'<path d="M5 6h8a4 4 0 0 1 4 4v10H9a4 4 0 0 0-4 1V6Zm14 0h2v15h-2"/><path d="M8 10h6m-6 4h6"/>',home:'<path d="m3 11 9-8 9 8M6 10v11h12V10m-9 11v-7h6v7"/>',month:'<rect x="4" y="5" width="16" height="16" rx="3"/><path d="M8 3v4m8-4v4M4 11h16m-11 4h2m3 0h2"/>',play:'<path d="m12 3 9 9-9 9-9-9 9-9Z"/><path d="m10 8 5 4-5 4V8Z"/>',library:'<path d="M4 4h5v17H4zM10 6h5v15h-5zM16 5l4-1 4 16-4 1z"/>',mood:'<circle cx="12" cy="12" r="9"/><path d="M8 10h.01M16 10h.01M8 15q4 3 8 0"/>',reset:'<path d="M3 9q4-6 9 0t9 0M3 16q4-6 9 0t9 0"/>',comfort:'<path d="M12 21S2 15 3 8c1-5 7-5 9-1 2-4 8-4 9 1 1 7-9 13-9 13Z"/>',experiment:'<path d="M9 3h6m-5 0v7L4 19q-1 2 2 2h12q3 0 2-2l-6-9V3M8 15h8"/>',map:'<circle cx="5" cy="6" r="3"/><circle cx="19" cy="7" r="3"/><circle cx="12" cy="19" r="3"/><path d="m7 8 4 8m6-7-4 7M8 6h8"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>'};return `<svg viewBox="0 0 26 26" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.mind}</svg>`}
function pondArt(){return `<svg viewBox="0 0 350 145" aria-hidden="true" fill="none"><path d="M0 93Q90 40 173 86t177-8v67H0Z" fill="#dce9e4"/><ellipse cx="212" cy="112" rx="104" ry="21" stroke="#8aada0"/><ellipse cx="212" cy="112" rx="72" ry="13" stroke="#8aada0"/><path d="M51 122V49a31 31 0 0 1 62 0v73M63 122V49a19 19 0 0 1 38 0v73" stroke="#668d82" stroke-width="1.4"/><path d="M72 59c20-21 38-12 23 12-19 0-28 14-23 29" stroke="#668d82" stroke-width="1.5"/><circle cx="269" cy="37" r="16" fill="#dfb580"/><path d="M144 67q24-16 41-3" stroke="#a297bd" stroke-width="1.5"/></svg>`}
function homePolished(){const hr=new Date().getHours();return `<section class="landing-hero"><div class="landing-meta"><span>${hr<12?'A softer morning':hr<18?'A little pause':'A quieter evening'}</span><span>${new Date().toLocaleDateString('en-IN',{day:'numeric',month:'short'})}</span></div><h1>Aaj ka mann,<br>apni raftaar.</h1><p>No catching up. No perfect words.<br>Bas, jahan ho wahin se.</p><div class="pond-art">${pondArt()}</div></section>${resurfaceCard()}<button class="landing-primary" data-go="mood"><span class="landing-icon">${spaceIcon('mood')}</span><span><strong>How am I feeling?</strong><small>Do-teen choices. Thodi si clarity.</small></span><span aria-hidden="true">›</span></button><div class="landing-duo"><a href="#mind" class="mind-door">${spaceIcon('mind')}<h2>Second mind</h2><p>Jo mann mein hai,<br>yahin rakh do.</p><span>Write freely</span></a><button class="pause-door" data-action="start-reset">${spaceIcon('reset')}<h2>Just a pause</h2><p>No explaining.<br>Your own pace.</p><span>Take a moment</span></button></div><a class="skills-home-link" href="#skills">${spaceIcon('map')}<span><strong>A little psychology, in practice</strong><small>Worry loops, thought checks, and meaningful actions. Your pace.</small></span></a><section class="space-list"><div class="section-head"><h2>A few familiar places</h2></div><a href="#comfort">${spaceIcon('comfort')}<span><strong>My comfort shelf</strong><small>A song, a photo, someone familiar</small></span><span>›</span></a><a href="#experiments">${spaceIcon('experiment')}<span><strong>Small experiments</strong><small>One thing to try. No daily homework.</small></span><span>›</span></a><a href="#mind-map">${spaceIcon('map')}<span><strong>Threads between thoughts</strong><small>Connections, drawn by you</small></span><span>›</span></a></section><a class="journey-feature" href="#play"><div>${spaceIcon('play')}<span>Stories to wander through</span></div><h2>A different path.<br>A little of yourself.</h2><p>Greek &amp; Indian mythology, your choices, and room for another meaning.</p><span>Choose a story</span></a><div class="home-foot"><a href="#month">My month</a><a href="#install">Install Antar</a><a href="#preferences">Make this space yours</a></div><p class="closing-note">Nothing to earn here. Just a place to return.</p>`}
function livingTabs(active){return `<div class="living-tabs"><a href="#mind" ${active==='mind'?'aria-current="page"':''}>My words</a><a href="#mind-map" ${active==='map'?'aria-current="page"':''}>Connections</a><a href="#experiments" ${active==='experiments'?'aria-current="page"':''}>Experiments</a></div>`}
function thoughtName(item){return item.title||item.text?.slice(0,55)||'A thought'}
function thoughtConnections(id){const edges=AntarLiving.links(personalItems).filter(x=>x.from===id||x.to===id);return edges.map(x=>{const other=personalItems.find(t=>t.id===(x.from===id?x.to:x.from));return `<div class="connection-row"><a href="#thought/${encodeURIComponent(other.id)}">${esc(thoughtName(other))}</a>${x.text?`<p class="small">${esc(x.text)}</p>`:''}<button class="text-btn" data-personal-remove="${esc(x.id)}">Disconnect</button></div>`}).join('')||'<p class="small">No connections yet. You choose what belongs together.</p>'}
function thoughtDetail(id){const item=personalItems.find(x=>x.kind==='thought'&&x.id===id);if(!item)return `<a class="install-link" href="#mind">‹ My words</a><h1>${personalReady?'This thought isn’t here.':'Opening your words…'}</h1><p class="sub">If you removed it, Undo is available in your Second mind until you reload.</p>`;return `<a class="install-link" href="#mind">‹ My words</a><p class="greeting">Your words · ${new Date(item.createdAt).toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'})}</p><h1>${esc(item.title||'As it came to you.')}</h1><p class="thought-full">${esc(item.text)}</p><div class="chips"><button class="secondary" data-mind-edit="${esc(item.id)}">Edit this thought</button><button class="text-btn" data-revisit-toggle="${esc(item.id)}">${item.revisit?'Remove from gentle resurfacing':'Choose for gentle resurfacing'}</button></div><button class="secondary" data-thought-check="${esc(item.id)}">Explore these words in a gentle thought check</button><p class="small">Your original stays unchanged. You choose what goes where.</p><h2>This feels related to…</h2>${thoughtConnections(id)}<button class="secondary" data-connect-from="${esc(id)}">Connect another thought</button><a class="install-link" href="#experiments">Turn an idea into a small experiment</a>${personalNotice()}`}
function thoughtMap(){const thoughts=personalItems.filter(x=>x.kind==='thought');if(!thoughts.some(x=>x.id===mapFocus))mapFocus=thoughts[0]?.id||'';const focus=thoughts.find(x=>x.id===mapFocus),edges=AntarLiving.links(personalItems).filter(x=>x.from===mapFocus||x.to===mapFocus);const neighbors=edges.map(x=>thoughts.find(t=>t.id===(x.from===mapFocus?x.to:x.from))).slice(0,6);let diagram='';if(focus){const positions=neighbors.map((x,i)=>({item:x,x:160+108*Math.cos((i/Math.max(neighbors.length,1))*Math.PI*2-Math.PI/2),y:160+105*Math.sin((i/Math.max(neighbors.length,1))*Math.PI*2-Math.PI/2)}));const node=(item,x,y,root=false)=>`<a href="#thought/${encodeURIComponent(item.id)}" aria-label="Open thought: ${esc(thoughtName(item))}"><rect x="${x-45}" y="${y-22}" width="90" height="44" rx="14" fill="${root?'#174e50':'#e6e3ef'}"/><text x="${x}" y="${y+4}" text-anchor="middle" fill="${root?'#fff':'#203f42'}" font-size="10">${esc(thoughtName(item).slice(0,18))}${thoughtName(item).length>18?'…':''}</text></a>`;diagram=`<svg class="thought-map" viewBox="0 0 320 320" role="group" aria-label="Connections you made for ${esc(thoughtName(focus))}">${positions.map(p=>`<path d="M160 160Q${p.x} 160 ${p.x} ${p.y}" stroke="#9eb6ac" fill="none" stroke-width="1.5"/>`).join('')}${positions.map(p=>node(p.item,p.x,p.y)).join('')}${node(focus,160,160,true)}</svg>`}
return `${livingTabs('map')}<p class="greeting">Your words, over time</p><h1>Ek baat se<br>doosri baat.</h1><p class="sub">A small map of connections you made. No automatic themes or psychological interpretation.</p>${!personalReady?'<p class="small">Opening your thoughts…</p>':''}${focus?`<label class="field" for="map-focus">A thought to look from</label><select id="map-focus" class="section-select">${thoughts.map(t=>`<option value="${esc(t.id)}" ${t.id===mapFocus?'selected':''}>${esc(thoughtName(t))}</option>`).join('')}</select><div class="map-paper">${diagram}<p class="small">${edges.length?'Tap a thought to read it. '+(edges.length>6?'Showing six connections here; all are listed below.':''):'A first point. Add a connection when one feels right.'}</p></div>${thoughtConnections(mapFocus)}`:'<div class="empty-space"><h2>Some words first.</h2><p>Save two thoughts in your Second mind. Connect them only if they feel related to you.</p><a class="install-link" href="#mind">Write a thought</a></div>'}${thoughts.length>=2?`<details ${mapTarget?'open':''}><summary>This feels related to…</summary><label class="field" for="map-target">Connect to</label><select id="map-target" class="section-select"><option value="">Choose another thought</option>${thoughts.filter(t=>t.id!==mapFocus).map(t=>`<option value="${esc(t.id)}" ${t.id===mapTarget?'selected':''}>${esc(thoughtName(t))}</option>`).join('')}</select><label class="field" for="map-label">In your words, how? <span class="small">(optional)</span></label><input id="map-label" maxlength="140" value="${esc(mapLabel)}" placeholder="For example: both are about asking for space"><button class="primary" data-living="connect">Save this connection</button></details>`:''}${lastPersonalRemoval?'<button class="secondary" data-personal="undo">Undo last removal</button>':''}${personalNotice()}`}
function experimentCards(){const items=personalItems.filter(x=>x.kind==='experiment').sort((a,b)=>Date.parse(b.updatedAt)-Date.parse(a.updatedAt));return items.map(item=>`<article class="experiment-card"><p class="small">${item.state==='done'?'Reflected on':item.state==='paused'?'Set aside for now':'When you’re ready'} · ${new Date(item.createdAt).toLocaleDateString('en-IN',{day:'numeric',month:'short'})}</p><h2>${esc(item.title)}</h2>${item.meaning||item.availableEnergy?`<div class="meaning-context">${item.meaning?`<span>${esc({connection:'Connection',enjoyment:'Enjoyment',meaning:'Personally important'}[item.meaning]||item.meaning)}</span>`:''}${item.availableEnergy?`<span>${esc({gentle:'Very little energy',some:'A little room',more:'More room today'}[item.availableEnergy]||item.availableEnergy)}</span>`:''}</div>`:''}${item.text?`<p class="sub">${esc(item.text)}</p>`:''}${item.result?`<div class="experiment-result"><p class="small">What you noticed</p><p class="thought-full">${esc(item.result)}</p><p class="small">${{helped:'You marked this helpful', 'not-helped':'You marked this not helpful',unsure:'Helpfulness left open'}[item.outcome||'unsure']}. An experience to reflect on, not proof of cause.</p></div>`:''}<div class="chips"><button class="text-btn" data-experiment-reflect="${esc(item.id)}">${item.result?'Edit my reflection':'What happened? (optional)'}</button><button class="text-btn" data-personal-remove="${esc(item.id)}">Remove</button></div></article>`).join('')||'<p class="empty">No experiment to keep up with. Add one only when it feels useful.</p>'}
function experimentsView(){const item=personalItems.find(x=>x.id===experimentEditing);return `${livingTabs('experiments')}<p class="greeting">A tiny personal experiment</p><h1>Bas ek cheez<br>try karke dekhein.</h1><a class="install-link" href="#skill/actions">Find a small action with meaning</a><p class="sub">“Ask for more time.” “Take a short walk.” Your own idea, at your own pace. No reminders or daily targets.</p>${item?`<div class="experiment-editor"><h2>${esc(item.title)}</h2><label class="field" for="experiment-result">What happened? What did you notice?</label><textarea id="experiment-result" maxlength="1600" placeholder="It can be messy, mixed, or still unclear.">${esc(experimentResult)}</textarea><label class="field" for="experiment-outcome">Did this feel helpful?</label><select id="experiment-outcome" class="section-select">${[['unsure','Not sure / leave open'],['helped','Helpful to me'],['not-helped','Not helpful to me']].map(([id,label])=>`<option value="${id}" ${experimentOutcome===id?'selected':''}>${label}</option>`).join('')}</select><label class="field" for="experiment-state">Where would you leave it?</label><select id="experiment-state" class="section-select">${[['done','Reflected on'],['open','Still exploring'],['paused','Set aside for now']].map(([id,label])=>`<option value="${id}" ${experimentState===id?'selected':''}>${label}</option>`).join('')}</select><button class="primary" data-living="reflect">Save my reflection</button><button class="text-btn" data-living="close-reflection">Close without saving</button></div>`:`<label class="field" for="experiment-title">One thing I might try</label><input id="experiment-title" maxlength="160" value="${esc(experimentTitle)}" placeholder="Ask for more time"><details><summary>A little context? Optional.</summary><label class="field" for="experiment-meaning">What matters in this action? (optional)</label><select id="experiment-meaning" class="section-select">${[['','Leave open'],['connection','Connection'],['enjoyment','Enjoyment'],['meaning','Something important to me']].map(([id,label])=>`<option value="${id}" ${experimentMeaning===id?'selected':''}>${label}</option>`).join('')}</select><label class="field" for="experiment-energy">Available energy (optional)</label><select id="experiment-energy" class="section-select">${[['','Leave open'],['gentle','Very little energy'],['some','A little room'],['more','More room today']].map(([id,label])=>`<option value="${id}" ${experimentEnergy===id?'selected':''}>${label}</option>`).join('')}</select><label class="field" for="experiment-plan">What would you like to explore?</label><textarea id="experiment-plan" maxlength="800" placeholder="For example: can I ask without overexplaining?">${esc(experimentPlan)}</textarea></details><button class="primary" data-living="experiment" ${personalReady?'':'disabled'}>Keep this experiment</button>`}<p class="note">Saved locally when you choose. Experiments don’t automatically create downtime logs or change your helpful-action history.</p><div class="divider"></div><h2>A little notebook of trying.</h2>${experimentCards()}${personalBackupControls()}`}
function preferencesView(){const choices=[['home','Antar home','A few paths, at your pace'],['mood','Feeling words','Start by naming what’s here'],['mind','Second mind','Start with somewhere to write'],['reset','A quiet reset','Begin with a pause'],['comfort','My comfort shelf','Something familiar first']];return `<a class="install-link" href="#home">‹ Home</a><p class="greeting">Make this space yours</p><h1>A familiar<br>place to begin.</h1><p class="sub">Choose what opens when you launch Antar. Links to a particular page still open that page.</p><div class="start-choices">${choices.map(([id,title,sub])=>`<button class="start-choice ${openingScreen===id?'selected':''}" data-opening="${id}" aria-pressed="${openingScreen===id}"><span>${spaceIcon(id)}</span><span><strong>${title}</strong><small>${sub}</small></span><span>${openingScreen===id?'✓':''}</span></button>`).join('')}</div><div class="divider"></div><h2>Gently, once in a while.</h2><p class="sub">Let Antar offer one thought or comforting line you chose to revisit. At most once a week, inside the app. No notifications.</p><label class="revisit-switch"><input id="revisit-enabled" type="checkbox" ${revisitState.enabled?'checked':''}>Gentle resurfacing is ${revisitState.enabled?'on':'off'}</label><p class="small">Off by default. Select individual thoughts or comforting words with “Choose for gentle resurfacing.” Photos, audio, contact details, and unselected thoughts are never offered.</p><p class="small">${personalItems.filter(x=>x.revisit&&['thought','words'].includes(x.kind)).length} selected ${personalItems.filter(x=>x.revisit&&['thought','words'].includes(x.kind)).length===1?'item':'items'}. “Not today” puts the offer away for this visit. Turning this off stops offers and keeps your saved content.</p><div class="home-foot"><a href="#mind">Choose a thought</a><a href="#comfort">Choose comforting words</a><a href="#settings">Privacy &amp; app controls</a></div><p class="note">These preferences stay in this browser. Unsaved drafts are never resurfaced.</p>`}
function resurfaceCard(){if(!personalReady||!revisitState.enabled||revisitDismissed)return '';if(revisitSession)revisitSession=personalItems.find(x=>x.id===revisitSession.id&&x.revisit)||null;if(!revisitSession){const item=AntarLiving.revisit(personalItems,revisitState);if(!item)return '';try{const next={...revisitState,lastShownAt:new Date().toISOString()};localStorage.setItem(REVISIT_KEY,JSON.stringify(next));revisitState=next;revisitSession=item;writePersonal({...item,lastRevisitedAt:next.lastShownAt,updatedAt:item.updatedAt},item.updatedAt).catch(()=>{});}catch{return ''}}const item=revisitSession;return `<section class="resurface-note"><p class="small">You chose to revisit this</p><h2>${esc(item.title||'A line from you')}</h2><p class="resurface-preview">${esc(item.text?.slice(0,220)||'')}</p><div class="chips"><a class="install-link" href="${item.kind==='thought'?'#thought/'+encodeURIComponent(item.id):'#comfort'}">Read in my own time</a><button class="text-btn" data-living="not-today">Not today</button><button class="text-btn" data-living="resurface-off">Turn off</button></div></section>`}
function persistRevisit(next){try{localStorage.setItem(REVISIT_KEY,JSON.stringify(next));revisitState=next;return true}catch{toast('This preference could not be saved. Try again.');return false}}
document.addEventListener('input',event=>{const e=event.target;if(e.id==='map-label')mapLabel=e.value;if(e.id==='experiment-title')experimentTitle=e.value;if(e.id==='experiment-plan')experimentPlan=e.value;if(e.id==='experiment-result')experimentResult=e.value});
document.addEventListener('change',event=>{const e=event.target;if(e.id==='map-focus'){mapFocus=e.value;mapTarget='';render(true)}if(e.id==='map-target')mapTarget=e.value;if(e.id==='experiment-meaning')experimentMeaning=e.value;if(e.id==='experiment-energy')experimentEnergy=e.value;if(e.id==='experiment-outcome')experimentOutcome=e.value;if(e.id==='experiment-state')experimentState=e.value;if(e.id==='revisit-enabled'){if(persistRevisit({...revisitState,enabled:e.checked})){revisitSession=null;revisitDismissed=false;render(true)}}});
document.addEventListener('click',async event=>{const el=event.target.closest('button');if(!el)return;try{if(el.dataset.opening){const value=AntarLiving.start(el.dataset.opening);localStorage.setItem(START_KEY,value);openingScreen=value;render(true);toast('Antar will open here next time.');return}if(el.dataset.connectFrom){mapFocus=el.dataset.connectFrom;mapTarget='';go('mind-map');return}if(el.dataset.revisitToggle){const item=personalItems.find(x=>x.id===el.dataset.revisitToggle);if(!item||!['thought','words'].includes(item.kind))return;await writePersonal({...item,revisit:!item.revisit,updatedAt:new Date().toISOString()},item.updatedAt);await refreshPersonal(true);render(true);toast(item.revisit?'Removed from resurfacing.':revisitState.enabled?'Chosen for a future gentle offer.':'Chosen. Turn on gentle resurfacing in My space preferences.');return}if(el.dataset.experimentReflect){const item=personalItems.find(x=>x.id===el.dataset.experimentReflect);if(experimentEditing&&experimentResult.trim()&&!confirm('Replace this unsaved reflection with another experiment?'))return;experimentEditing=item.id;experimentVersion=item.updatedAt;experimentResult=item.result||'';experimentOutcome=item.outcome||'unsure';experimentState=item.state==='open'?'done':item.state;render();return}const action=el.dataset.living;if(action==='connect'){if(!mapFocus||!mapTarget||mapFocus===mapTarget)return toast('Choose two different saved thoughts.');const latest=await readPersonal();if(![mapFocus,mapTarget].every(id=>latest.some(x=>x.id===id&&x.kind==='thought')))return toast('One thought changed or was removed. Refresh your saved items.');if(latest.some(x=>x.id===AntarLiving.linkId(mapFocus,mapTarget)))return toast('These thoughts are already connected.');const now=new Date().toISOString();await writePersonal({id:AntarLiving.linkId(mapFocus,mapTarget),kind:'link',from:mapFocus,to:mapTarget,text:mapLabel.trim(),createdAt:now,updatedAt:now});mapTarget='';mapLabel='';await refreshPersonal(true);render(true);toast('Connection saved, in your words.')}if(action==='experiment'){if(!experimentTitle.trim())return toast('Choose one small thing you might try.');const now=new Date().toISOString();await writePersonal({id:personalId(),kind:'experiment',title:experimentTitle.trim(),text:experimentPlan.trim(),meaning:experimentMeaning,availableEnergy:experimentEnergy,state:'open',outcome:'unsure',result:'',createdAt:now,updatedAt:now});experimentTitle='';experimentPlan='';experimentMeaning='';experimentEnergy='';await refreshPersonal(true);render(true);toast('Kept. Come back only if you want.')}if(action==='reflect'){const item=personalItems.find(x=>x.id===experimentEditing);if(!item)return;await writePersonal({...item,result:experimentResult.trim(),outcome:experimentOutcome,state:experimentState,updatedAt:new Date().toISOString()},experimentVersion);experimentEditing='';experimentResult='';await refreshPersonal(true);render(true);toast('Your reflection is saved.')}if(action==='close-reflection'){if(experimentResult.trim()&&!confirm('Close this reflection without saving your changes?'))return;experimentEditing='';experimentResult='';render(true)}if(action==='not-today'){revisitDismissed=true;revisitSession=null;render(true)}if(action==='resurface-off'){if(persistRevisit({...revisitState,enabled:false})){revisitSession=null;render(true)}}}catch(error){toast(error.message||'Could not save that change. Your draft is still here.')}});

window.addEventListener('storage',event=>{if(event.key===REVISIT_KEY){try{const saved=JSON.parse(event.newValue||'{}');revisitState={enabled:saved.enabled===true,lastShownAt:saved.lastShownAt||''};revisitSession=null;if(['home','mind','comfort','preferences'].includes(route))render(true)}catch{}}});
